SourceCode.Declaration:
class TFMCommandResponseNotify extends TFMCommandResponse
{
    str notificationId;
    str header;
    str message;
    str backgroundColor;
    str icon;
    int duration;

}

Method.Source:
public static TFMCommandResponseNotify Construct(str _notificationId, str _header, str _message = '', str _backgroundColor = '', str _icon = '', int _duration = 0)
{
    TFMCommandResponseNotify response = new TFMCommandResponseNotify();
    response.notificationId = _notificationId;
    response.header = _header;
    response.message = _message;
    response.backgroundColor = _backgroundColor;
    response.icon = _icon;
    response.duration = _duration;
    return response;
}

public void appendToXML(XmlElement _element)
{
    XmlDocument xmlDoc = _element.ownerDocument();
    XmlElement notifyElement = xmlDoc.createElement('notify');
    notifyElement.setAttribute('id', notificationId);
    notifyElement.setAttribute('header', header);
    if (message)
    {
        notifyElement.setAttribute('text', message);
    }

    notifyElement.setAttribute('backgroundColor', this.parmBackgroundColor());

    if (icon)
    {
        notifyElement.setAttribute('icon', icon);
    }
    if (duration)
    {
        notifyElement.setAttribute('duration', int2Str(duration));
    }
    _element.appendChild(notifyElement);
}

public str parmNotificationId(str _notificationId = notificationId)
{
    notificationId = _notificationId;
    return notificationId;
}

public str parmHeader(str _header = header)
{
    header = _header;
    return header;
}

public str parmMessage(str _message = message)
{
    message = _message;
    return message;
}

public str parmBackgroundColor(str _backgroundColor = backgroundColor)
{
    backgroundColor = _backgroundColor;
    return backgroundColor ? backgroundColor : '#639754';
}

public str parmIcon(str _icon = icon)
{
    icon = _icon;
    return icon;
}

public int parmDuration(int _duration = duration)
{
    duration = _duration;
    return duration;
}
